# Iterative binary search - O(log n)

def binary_search(arr, x):
    left = 0
    right = len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            return mid
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return -1

if __name__ == '__main__':
    arr = list(range(0, 1000))
    print(binary_search(arr, 777))

# Recursive binary search - O(log n)

def binary_search_rec(arr, x, left, right):
    if left > right:
        return -1
    mid = (left + right) // 2
    if arr[mid] == x:
        return mid
    elif arr[mid] < x:
        return binary_search_rec(arr, x, mid + 1, right)
    else:
        return binary_search_rec(arr, x, left, mid - 1)

if __name__ == '__main__':
    arr = list(range(0, 2000))
    print(binary_search_rec(arr, 1500, 0, len(arr) - 1))

# Fast power - O(log n)

def fast_pow(a, n):
    result = 1
    base = a
    exp = n
    while exp > 0:
        if exp & 1:
            result *= base
        base *= base
        exp >>= 1
    return result

if __name__ == '__main__':
    print(fast_pow(2, 20))

