# Triple nested loops - O(n^3)

def count_triplets(arr):
    n = len(arr)
    cnt = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if arr[i] + arr[j] + arr[k] == 0:
                    cnt += 1
    return cnt

