# Naive matrix multiplication - O(n^3)

def matmul(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

if __name__ == '__main__':
    n = 60
    A = [[1]*n for _ in range(n)]
    B = [[1]*n for _ in range(n)]
    C = matmul(A, B)
    print(C[0][0])

# Three nested loops - combination processing - O(n^3)

def process_three_way(arr):
    n = len(arr)
    s = 0
    for a in arr:
        for b in arr:
            for c in arr:
                s += (a * b) + c
    return s

if __name__ == '__main__':
    arr = list(range(200))
    print(process_three_way(arr) % 1000)

# Naive Fibonacci - exponential O(2^n)

def fib(n):
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

if __name__ == '__main__':
    print(fib(30))

# Generate all subsets (power set) - O(2^n)

def subsets(arr):
    res = []
    n = len(arr)
    for mask in range(1 << n):
        cur = []
        for i in range(n):
            if mask & (1 << i):
                cur.append(arr[i])
        res.append(cur)
    return res

if __name__ == '__main__':
    arr = [1,2,3,4,5,6,7,8]
    print(len(subsets(arr)))

# Counting permutations (conceptual) - O(n!)

def count_perms(n):
    if n <= 1:
        return 1
    total = 0
    for i in range(n):
        # choose element i and count perms of remaining n-1
        total += count_perms(n - 1)
    return total

if __name__ == '__main__':
    print(count_perms(8))
